import {mountVoxProFace} from './vox-pro-face.js';
import {micColorGains} from './vox-mic-model.js';
export const MIC_BANKS=Object.freeze([['SOURCE / TARGET',['source','target']],['TONE',['proximity','presence','air']],['PARALLEL',['mix']]]);
const profileName=i=>'Profil '+(Math.max(0,Math.min(3,Math.round(i)))+1);
const chart='<svg viewBox="0 0 360 140" role="img" aria-label="Gains nominaux des trois filtres"><rect x="1" y="1" width="358" height="138" rx="4" fill="#171520" stroke="#716782"/>'+[-12,-6,0,6,12].map(v=>'<path d="M32 '+(61-v*3)+'H338" stroke="'+(v===0?'#9387a4':'#393445')+'"/><text x="28" y="'+(64-v*3)+'" fill="#d5cbe8" font-size="9" text-anchor="end">'+v+'</text>').join('')+['LOW 180 Hz','PRES 3.2 kHz','AIR 9.5 kHz'].map((label,i)=>'<rect data-mic-bar="'+i+'" x="'+(65+i*101)+'" y="61" width="43" height="0" rx="2" fill="'+['#96b6d0','#b7a5e6','#d6b1a5'][i]+'"/><text data-mic-gain="'+i+'" x="'+(86+i*101)+'" y="112" fill="#e6cdfd" text-anchor="middle" font-size="11"/><text x="'+(86+i*101)+'" y="126" fill="#d5cbe8" text-anchor="middle" font-size="9">'+label+'</text>').join('')+'</svg>';
export function mountVoxMic(root,options){return mountVoxProFace(root,{...options,id:'vox-mic',title:'MIC COLOR 06',subtitle:'GENERIC SOURCE / TARGET TONE',banks:MIC_BANKS,display:'<div class="vox-pro-profile"><div>SOURCE<output data-mic-source></output></div><div>TARGET<output data-mic-target></output></div></div>'+chart+'<div class="vox-pro-readouts"><output data-mic-status></output><output data-mic-mix></output></div><small>Gains configurés des trois filtres du chemin traité, pas une mesure de réponse acoustique. Profils génériques, sans émulation propriétaire.</small>',footer:'LOW SHELF · PRESENCE · HIGH SHELF · NATIVE DSP',paint(face,s){
 face.querySelector('[data-mic-source]').textContent=profileName(s.source);face.querySelector('[data-mic-target]').textContent=profileName(s.target);
 micColorGains(s).forEach((gain,i)=>{const b=face.querySelector('[data-mic-bar="'+i+'"]');b.setAttribute('y',61-Math.max(0,gain)*3);b.setAttribute('height',Math.abs(gain)*3);face.querySelector('[data-mic-gain="'+i+'"]').textContent=(gain>0?'+':'')+gain.toFixed(1)+' dB';});
 face.querySelector('[data-mic-status]').textContent=s.enabled===false?'BYPASS':s.mix===0?'DRY':'ACTIVE';face.querySelector('[data-mic-mix]').textContent='WET '+Math.round((s.enabled===false?0:s.mix)*100)+'%';
 }});}
